WITH a AS (SELECT r.DATASET_NAME,TRY_PARSE_JSON(d.PAYLOAD_JSON) AS p FROM VECTOR_RESEARCH.RAW.RESEARCH_ACQUISITION_RUNS r JOIN VECTOR_RESEARCH.RAW.RESEARCH_ACQUISITION_ROWS d ON r.RUN_ID=d.RUN_ID), manifests AS (SELECT ACCESSION,MAX(DOCUMENT_COUNT) AS expected,COUNT(*) AS n FROM VECTOR_RESEARCH.RAW.SEC_FILING_PACKAGE_MANIFESTS GROUP BY ACCESSION), documents AS (SELECT ACCESSION,COUNT(DISTINCT DOCUMENT_NAME) AS actual,COUNT(*) AS n FROM VECTOR_RESEARCH.RAW.SEC_FILING_DOCUMENTS GROUP BY ACCESSION)
SELECT 'acquisition_coverage' AS SECTION,OBJECT_CONSTRUCT_KEEP_NULL('dataset',DATASET_NAME,'type',p:record_type::STRING,'gpu',p:context:gpu_type::STRING,'rows',COUNT(*),'min_index_timestamp',MIN(p:data:timestamp::STRING),'max_index_timestamp',MAX(p:data:timestamp::STRING),'min_asof',MIN(p:context:as_of::STRING),'max_asof',MAX(p:context:as_of::STRING),'min_snapshot',MIN(p:context:snapshot_as_of::STRING),'max_snapshot',MAX(p:context:snapshot_as_of::STRING),'min_report_month',MIN(p:context:report_month::STRING),'max_report_month',MAX(p:context:report_month::STRING),'first_filing_date',MIN(p:data:filing_date::STRING),'last_filing_date',MAX(p:data:filing_date::STRING),'min_block_time_ns',MIN(p:data:block_time_ns::NUMBER),'max_block_time_ns',MAX(p:data:block_time_ns::NUMBER),'min_server_time',MIN(p:data:server_time::STRING),'max_server_time',MAX(p:data:server_time::STRING),'missing_or_nonpositive_quote',COUNT_IF(ARRAY_CONTAINS('missing_or_nonpositive_quote'::VARIANT,p:quality_flags)),'stale_quote',COUNT_IF(ARRAY_CONTAINS('older_than_five_minutes_at_close'::VARIANT,p:quality_flags))) AS DETAIL FROM a GROUP BY DATASET_NAME,p:record_type::STRING,p:context:gpu_type::STRING
UNION ALL SELECT 'sec_reconciliation',OBJECT_CONSTRUCT_KEEP_NULL('manifest_accessions',COUNT(m.ACCESSION),'document_accessions',COUNT(d.ACCESSION),'duplicate_manifest_accessions',COUNT_IF(m.n>1),'duplicate_document_accessions',COUNT_IF(d.n>d.actual),'mismatched_document_counts',COUNT_IF(m.expected<>d.actual),'manifest_without_documents',COUNT_IF(m.ACCESSION IS NOT NULL AND d.ACCESSION IS NULL),'documents_without_manifest',COUNT_IF(d.ACCESSION IS NOT NULL AND m.ACCESSION IS NULL)) FROM manifests m FULL OUTER JOIN documents d ON m.ACCESSION=d.ACCESSION
